// El cupón vigente se calcula contra la fecha real de hoy (ver
// cy.obtenerCuponVigente('AL30'), agenda.commands.js) en vez de hardcodear
// uno: un cupón fijo se aleja del "Fecha desde" con el correr de los
// meses hasta superar el límite de 6 meses que impone el backend.
cy.obtenerCuponVigente('AL30').then(({ label, fechaDesde }) => {
  cy.irAAgenda();
  cy.seleccionarTab('Bonos');
  cy.filtrarPendientesPorFecha('Pendiente', fechaDesde, 'Fecha desde');
  cy.buscarDepositario('depositario CYPRESS');
  cy.cobrarInstrumento(label);
  cy.cobrarCupon();
  cy.validarInstrumentoCobrado('depositario CYPRESS', label, fechaDesde);
});

cy.obtenerCuponVigente('AL30').then(({ label, fechaDesde }) => {
  cy.irAAgenda();
  cy.seleccionarTab('Bonos');
  cy.filtrarCobradosConceptoPorFecha('Pendiente', fechaDesde);
  cy.buscarDepositario('depositario CYPRESS');
  cy.eliminarCobro(label);
  // Verificar que se muestre el cupón en pendiente.
  cy.seleccionarTab('Bonos');
  cy.filtrarPendientesPorFecha('Cobrado', fechaDesde, 'Fecha desde');
  cy.buscarDepositario('depositario CYPRESS');
  cy.validarInstrumentoPendiente(label);
});

